<script setup lang="ts">import type{CrmTicket}from"~/composables/useCrm";definePageMeta({layout:"default"});useSeoMeta({title:"CRM و پشتیبانی | هفت‌سو",robots:"noindex,nofollow"});const{assign,customer,load,loadCustomer,message,metrics,pending,selected,tickets,transition}=useCrm(),state=ref("all");onMounted(()=>load());watch(state,(value:string)=>load(value));watch(selected,(item:CrmTicket|null)=>{if(item)loadCustomer(item.customer_id)});</script><template><main id="main-content" class="crm-admin content-container"><header class="crm-header"><div><p class="eyebrow">مرکز ارتباط با مشتری</p><h1>CRM و پشتیبانی هفت‌سو</h1><p>صف چندکاناله، SLA، تاریخچه یکپارچه و نمای ۳۶۰ درجه کاربر.</p></div><label>نمای صف<select v-model="state"><option value="all">همه تیکت‌ها</option><option value="open">باز</option><option value="assigned">تخصیص‌یافته</option><option value="waiting_customer">منتظر کاربر</option><option value="resolved">حل‌شده</option></select></label></header><CrmMetrics :metrics="metrics"/><UiState v-if="pending" kind="loading" title="در حال دریافت تیکت‌ها" description="صف و SLA محاسبه می‌شود."/><UiState v-else-if="!tickets.length" kind="empty" title="تیکتی در این صف نیست" description="فیلتر دیگری انتخاب کنید."/><div v-else class="crm-layout"><CrmTicketQueue :items="tickets" :active-id="selected?.id" @select="selected=$event"/><CrmTicketWorkspace v-if="selected" :item="selected" @assign="assign" @transition="transition"/><Customer360Panel :customer="customer"/></div><p v-if="message" class="post-action-message" role="status">{{message}}</p></main></template>
